from taf.internal.impact_radar import log_radar

from .available_devices import SupportedOpticalSwitchVendors


class Factory:

    @staticmethod
    def _create(vendor, model, addr, **kwargs):
        log_radar(
            "Tracking the usage of optical switches",
            vendor=vendor,
            model=model,
        )

        vendor = SupportedOpticalSwitchVendors.get_vendor(vendor)
        switch_model = vendor.get_model(model)
        return switch_model(addr, **kwargs)

    @classmethod
    def create(cls, optical_switch, **kwargs):
        if not isinstance(optical_switch, str):

            # OpticalSwitch objects from taf.config.testline can have port set as None, we need to check it
            # to make sure we can use default values correctly later on in __init__ methods of devices.
            # TLDR: If port is not set, don't pass it as argument and let default values take precedence
            port = kwargs.pop("port", optical_switch.port)
            if port is not None:
                kwargs["port"] = port

            vendor = optical_switch.vendor
            model = optical_switch.model
            addr = optical_switch.addr

        else:
            vendor = optical_switch
            model = kwargs.pop("model")
            addr = kwargs.pop("addr")

        return cls._create(vendor, model, addr, **kwargs)
